const paths={spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z M20 2v4 M18 4h4',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',database:'M20 5c0 2-4 3-8 3S4 7 4 5s4-3 8-3 8 1 8 3z M4 5v14c0 2 4 3 8 3s8-1 8-3V5 M4 12c0 2 4 3 8 3s8-1 8-3',sliders:'M4 4v16 M12 4v16 M20 4v16 M1 8h6 M9 16h6 M17 10h6',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z m-4 9 3 3 5-6',layers:'m12 3 10 5-10 5L2 8z M2 12l10 5 10-5 M2 16l10 5 10-5',help:'M9 8a3 3 0 0 1 6 0c0 2-3 2-3 5 M12 17h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',menu:'M3 6h18 M3 12h18 M3 18h18',arrow:'M4 12h16 m-6-6 6 6-6 6',send:'M12 20V4 m-6 6 6-6 6 6',chart:'M3 3v18h18 M7 16v-5 M12 16V6 M17 16v-8',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',plus:'M12 4v16 M4 12h16',close:'m6 6 12 12 M6 18 18 6',edit:'m15 4 5 5 M4 20l5-1L21 7l-4-4L5 15z',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',share:'M8 12l9-6 M8 12l9 6 M8 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M22 5a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M22 19a3 3 0 1 1-6 0 3 3 0 0 1 6 0',play:'m9 6 10 6-10 6z M3 3h18v18H3z',filter:'M3 4h18l-7 8v7l-4 2v-9z',refresh:'M20 8a9 9 0 1 0 1 7 M20 3v5h-5',link:'m10 13 4-4 M8 15l-2 2a4 4 0 0 1-5-5l5-5a4 4 0 0 1 6 0 M16 9l2-2a4 4 0 0 0-5-5l-5 5',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h8',check:'m5 12 4 4L20 5',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',back:'m14 5-7 7 7 7',table:'M3 3h18v18H3z M3 9h18 M9 3v18 M3 15h18',trash:'M3 6h18 M8 6V3h8v3 M6 6l1 15h10l1-15',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M17 3a4 4 0 0 1 0 8 M22 21v-3a4 4 0 0 0-3-4'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.chart}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n);
const compact=n=>Math.abs(n)<10000?money(n):n>=1e6?`R$ ${(n/1e6).toFixed(2).replace('.',',')} mi`:`R$ ${(n/1000).toFixed(0)} mil`;
function hydrate(){ $$('i[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon)); }
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
function showModal(title,content){$('#modal').innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="Fechar">${icon('close')}</button></div>${content}`;$('#modal').showModal();hydrate();}
function home(){return `<div class="home"><div class="home-top"><span class="eyebrow">SEU PONTO DE PARTIDA</span><span class="date">Workspace de demonstração</span></div><section class="welcome"><div class="ai-symbol">${icon('spark')}</div><h1>Boas perguntas.<br><span>Grandes descobertas.</span></h1><p>Olá, João. O que seus dados podem responder hoje?</p><form id="home-chat" class="composer"><textarea id="home-prompt" aria-label="Sua pergunta para o Prometeu" placeholder="Crie um dashboard com os custos da minha área neste mês..."></textarea><div class="composer-footer"><button class="source-pill" type="button" data-action="source">${icon('database')} ${esc(sourceName())}⌄</button><div class="composer-hint"><span>Enter para enviar</span><button type="submit" class="send" aria-label="Enviar pergunta">${icon('send')}</button></div></div></form><div class="suggestions"><button class="suggestion" data-prompt="Crie um dashboard dos custos da minha área em setembro">${icon('chart')} Custos da minha área</button><button class="suggestion" data-prompt="Compare o realizado com o orçamento">${icon('layers')} Realizado × orçamento</button><button class="suggestion" data-prompt="Simule uma redução de custos de 10%">${icon('sliders')} Simular um cenário</button></div><div id="home-result" aria-live="polite"></div></section><section class="home-divider"><div class="section-title"><h2>Continue de onde parou</h2><a class="text-link" href="#dashboards">Ver meus dashboards ${icon('arrow')}</a></div><div class="recent-grid"><button class="recent-card" data-action="open-example"><div class="recent-header"><span class="tag blue">${icon('chart')} Dashboard de exemplo</span>${icon('arrow')}</div><h3>Visão de custos · Tecnologia</h3><p>Setembro de 2026 · SAP S/4HANA demonstrativo</p><div class="mini-chart" aria-hidden="true">${[40,56,48,61,50,72,57,78,65,87,70,93].map(n=>`<span style="height:${n}%"></span>`).join('')}</div><div class="recent-meta"><span>4 indicadores · 4 visualizações</span><span>Somente dados fictícios</span></div></button><article class="recent-card explore-card"><div><span class="eyebrow" style="color:#9fabec">DO DADO À POSSIBILIDADE</span><h3 style="font-size:20px;margin-top:13px">E se você pudesse<br>testar antes de decidir?</h3><p>Compare cenários e veja o efeito de cada escolha no seu orçamento.</p></div><a class="btn" href="#planejamento">Explorar planejamento ${icon('arrow')}</a><div class="orb" aria-hidden="true"></div></article></div></section></div>`;}
const colors=['#1b34c8','#5b76f7','#92a3ed','#bbc7f6','#dce3fc'];
const months={'2026-04':'Abril de 2026','2026-05':'Maio de 2026','2026-06':'Junho de 2026','2026-07':'Julho de 2026','2026-08':'Agosto de 2026','2026-09':'Setembro de 2026'};
const categories=['Infraestrutura','Pessoas','Licenças','Serviços','Viagens'];
const demoRows=[];
Object.keys(months).forEach((month,mi)=>['Tecnologia','Operações','Comercial'].forEach((area,ai)=>categories.forEach((cat,ci)=>demoRows.push({date:month+'-01',area,category:cat,actual:Math.round([420000,360000,240000,180000,84000][ci]*[.79,.85,.82,.91,.96,1][mi]*[1,.7,.52][ai]),budget:Math.round([400000,350000,250000,200000,100000][ci]*[.82,.87,.9,.94,.98,1][mi]*[1,.74,.55][ai])}))));
const defaultDashboard=()=>({id:'demo',title:'Visão de custos · Tecnologia',source:'demo',period:'2026-09',area:'Tecnologia',categories:[],trendType:'bar',mixType:'donut',trendTitle:'Evolução dos custos',mixTitle:'Custos por categoria',tableTitle:'Detalhamento dos custos',showBudget:true,messages:[],updated:new Date().toISOString()});
let state={dashboards:[defaultDashboard()],sources:[],current:'demo',chatOpen:true,scenario:{infra:0,people:0,services:0},scenarios:[]};
try{const saved=JSON.parse(localStorage.getItem('prometeu-v1'));if(saved&&Array.isArray(saved.dashboards)&&saved.dashboards.length&&Array.isArray(saved.sources))state={...state,...saved};}catch{}
let shared=false;
try{const q=new URLSearchParams(location.hash.split('?')[1]||'');if(q.has('snapshot')){const raw=JSON.parse(decodeURIComponent(escape(atob(q.get('snapshot')))));if(!raw||!Array.isArray(raw.rows)||raw.rows.length>5000)throw Error('Snapshot inválido');const rows=validateRows(raw.rows);state={...state,dashboards:[{...defaultDashboard(),...pickDashboard(raw.dashboard),id:'snapshot',source:'snapshot'}],sources:[{id:'snapshot',name:'Snapshot compartilhado',rows}],current:'snapshot'};shared=true;}}catch{setTimeout(()=>toast('Este link de snapshot é inválido. Abrimos o exemplo.'),200);}
function sanitizeStudio(input){
 if(!input||typeof input!=='object')return undefined;
 const safe={page:'overview',selected:'trend',order:[],options:{},extras:[]},base=['trend','mix','table','waterfall'];
 for(const v of (Array.isArray(input.extras)?input.extras:[]).slice(0,20)){
  if(!v||!/^w[0-9]+$/.test(v.id)||!['trend','mix','table','waterfall','text'].includes(v.kind)||base.includes(v.id))continue;
  base.push(v.id);safe.extras.push({id:v.id,kind:v.kind,title:String(v.title||'Visualização').slice(0,100),type:['bar','line','area','donut','table','waterfall','text'].includes(v.type)?v.type:'bar',text:String(v.text||'').slice(0,2000)});
 }
 safe.order=[...new Set((Array.isArray(input.order)?input.order:base).filter(id=>base.includes(id)))];if(!safe.order.length)safe.order=['trend'];
 safe.selected=safe.order.includes(input.selected)?input.selected:safe.order[0];
 safe.waterfallTitle=String(input.waterfallTitle||'Variação por categoria').slice(0,100);
 for(const id of base){const o=input.options?.[id];if(!o||typeof o!=='object')continue;const n={};for(const k of ['color','comparisonColor'])if(/^#[a-f0-9]{6}$/i.test(o[k]))n[k]=o[k];for(const k of ['legend','labels','wide'])if(typeof o[k]==='boolean')n[k]=o[k];if(['auto','mil','mi'].includes(o.unit))n.unit=o.unit;if([0,1,2].includes(o.decimals))n.decimals=o.decimals;n.subtitle=String(o.subtitle||'').slice(0,120);safe.options[id]=n;}
 return safe;
}
function pickDashboard(d){if(!d||typeof d!=='object')return{};const r={};for(const k of ['title','period','area','trendTitle','mixTitle','tableTitle'])if(typeof d[k]==='string')r[k]=d[k].slice(0,150);if(['bar','line','area','table'].includes(d.trendType))r.trendType=d.trendType;if(['donut','bar','table'].includes(d.mixType))r.mixType=d.mixType;r.showBudget=d.showBudget!==false;r.categories=Array.isArray(d.categories)?d.categories.filter(v=>typeof v==='string').slice(0,100):[];if(d.studio)r.studio=sanitizeStudio(d.studio);if(d.pro)r.pro=cleanPro(d.pro);return r;}
function persist(){if(shared)return;try{localStorage.setItem('prometeu-v1',JSON.stringify(state));}catch{toast('O armazenamento local está cheio. As alterações duram nesta sessão.');}}
function dash(){return state.dashboards.find(d=>d.id===state.current)||state.dashboards[0];}
function sourceRows(d=dash()){return d.source==='demo'?demoRows:(state.sources.find(s=>s.id===d.source)?.rows||[]);}
function sourceName(d=dash()){return d.source==='demo'?'SAP S/4HANA · demonstração':state.sources.find(s=>s.id===d.source)?.name||'Fonte indisponível';}
function selectRows(d=dash(),allPeriods=false){return sourceRows(d).filter(r=>(allPeriods||r.date.slice(0,7)===d.period)&&(d.area==='Todas as áreas'||r.area===d.area)&&(!d.categories.length||d.categories.includes(r.category)));}
function totals(rows){return rows.reduce((t,r)=>({actual:t.actual+r.actual,budget:t.budget+r.budget}),{actual:0,budget:0});}
function group(rows,key){const map=new Map();rows.forEach(r=>{const k=key==='month'?r.date.slice(0,7):r[key];const v=map.get(k)||{label:k,actual:0,budget:0};v.actual+=r.actual;v.budget+=r.budget;map.set(k,v);});return [...map.values()].sort((a,b)=>key==='month'?a.label.localeCompare(b.label):b.actual-a.actual);}
function periodLabel(p){return months[p]||new Date(p+'-02T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'});}
function trendRows(d=dash()){return group(selectRows(d,true).filter(r=>r.date.slice(0,7)<=d.period),'month').slice(-6);}
function metrics(d=dash()){const t=totals(selectRows(d));const series=trendRows(d).slice(-3);return {...t,delta:t.budget-t.actual,percent:t.budget?(t.budget-t.actual)/t.budget*100:0,forecast:series.length?series.reduce((s,r)=>s+r.actual,0)/series.length:0};}
function kpis(d=dash()){const m=metrics(d);return `<div class="kpi-grid"><article class="kpi focus"><div class="kpi-label">Custo realizado ${icon('chart')}</div><div class="kpi-value">${compact(m.actual)}</div><div class="kpi-foot">${esc(periodLabel(d.period))}</div></article><article class="kpi"><div class="kpi-label">Orçamento ${icon('layers')}</div><div class="kpi-value">${compact(m.budget)}</div><div class="kpi-foot">Base de comparação do período</div></article><article class="kpi"><div class="kpi-label">${m.delta>=0?'Saldo disponível':'Acima do orçamento'} ${icon('sliders')}</div><div class="kpi-value">${compact(Math.abs(m.delta))}</div><div class="kpi-foot ${m.delta>=0?'positive':'danger-text'}">${Math.abs(m.percent).toFixed(1).replace('.',',')}% ${m.delta>=0?'abaixo':'acima'} do orçamento</div></article><article class="kpi"><div class="kpi-label">Projeção · próximo mês ${icon('clock')}</div><div class="kpi-value">${compact(m.forecast)}</div><div class="kpi-foot">Média dos últimos ${Math.min(3,trendRows(d).length)} meses · estimativa</div></article></div>`;}
function dataTable(rows,detail=false){return `<div class="table-wrap"><table><thead><tr><th>${detail?'Categoria':'Período'}</th><th class="number">Realizado</th><th class="number">Orçamento</th><th class="number">Saldo</th>${detail?'<th class="number">Participação</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr><td>${detail?`<button class="text-link" data-drill="${esc(r.label)}">${esc(r.label)}</button>`:esc(periodLabel(r.label))}</td><td class="number">${money(r.actual)}</td><td class="number">${money(r.budget)}</td><td class="number ${(r.budget-r.actual)>=0?'positive':'danger-text'}">${money(r.budget-r.actual)}</td>${detail?`<td class="number">${(r.actual/(rows.reduce((s,x)=>s+x.actual,0)||1)*100).toFixed(1).replace('.',',')}%</td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function trendChart(d=dash()){const data=trendRows(d);if(!data.length)return '<div class="no-data">Não há dados para este recorte.</div>';if(d.trendType==='table')return dataTable(data);const max=Math.max(...data.map(r=>Math.max(r.actual,d.showBudget?r.budget:0)),1)*1.15;const W=620,H=230,L=52,R=15,T=20,B=34,pw=W-L-R,ph=H-T-B;const x=i=>L+(i+.5)*pw/data.length,y=v=>T+ph-v/max*ph;let s=`<svg class="plot" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(d.trendTitle)}: ${data.map(r=>esc(periodLabel(r.label))+', '+money(r.actual)).join('; ')}">`;for(let i=0;i<4;i++){const v=max*i/3;s+=`<line class="gridline" x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}"/><text x="${L-10}" y="${y(v)+4}" text-anchor="end">${max>=1e6?(v/1e6).toFixed(1).replace('.',',')+' mi':max>=10000?(v/1000).toFixed(0)+' mil':Math.round(v).toLocaleString('pt-BR')}</text>`;}if(d.trendType==='line'){if(d.showBudget)s+=`<polyline points="${data.map((r,i)=>`${x(i)},${y(r.budget)}`).join(' ')}" fill="none" stroke="#a8b6f5" stroke-width="3" stroke-dasharray="6 5"/>`;s+=`<polygon points="${x(0)},${y(0)} ${data.map((r,i)=>`${x(i)},${y(r.actual)}`).join(' ')} ${x(data.length-1)},${y(0)}" fill="#1b34c80b"/><polyline points="${data.map((r,i)=>`${x(i)},${y(r.actual)}`).join(' ')}" fill="none" stroke="#1b34c8" stroke-width="3"/>`;}data.forEach((r,i)=>{const bw=Math.min(22,pw/data.length/3);if(d.trendType==='bar'){if(d.showBudget)s+=`<rect x="${x(i)+2}" y="${y(r.budget)}" width="${bw}" height="${y(0)-y(r.budget)}" rx="3" fill="#d7def9"><title>Orçamento: ${money(r.budget)}</title></rect>`;s+=`<rect class="point" data-month="${esc(r.label)}" tabindex="0" role="button" aria-label="Filtrar ${esc(periodLabel(r.label))}" x="${x(i)-bw-2}" y="${y(r.actual)}" width="${bw}" height="${y(0)-y(r.actual)}" rx="3" fill="#1b34c8"><title>${esc(periodLabel(r.label))}: ${money(r.actual)}</title></rect>`;}else s+=`<circle class="point" data-month="${esc(r.label)}" tabindex="0" role="button" aria-label="Filtrar ${esc(periodLabel(r.label))}" cx="${x(i)}" cy="${y(r.actual)}" r="5" fill="#1b34c8" stroke="white" stroke-width="2"><title>${money(r.actual)}</title></circle>`;s+=`<text x="${x(i)}" y="${H-9}" text-anchor="middle">${new Date(r.label+'-02T12:00:00').toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</text>`;});return s+'</svg>';}
function mixChart(d=dash()){const rows=group(selectRows(d),'category');if(!rows.length)return '<div class="no-data">Não há dados neste recorte.</div>';if(d.mixType==='table')return dataTable(rows,true);if(d.mixType==='bar')return `<div class="bar-list">${rows.map((r,i)=>`<button class="bar-row" data-drill="${esc(r.label)}"><span>${esc(r.label)}</span><span class="bar-track"><span style="width:${r.actual/Math.max(...rows.map(x=>x.actual),1)*100}%;background:${colors[i%5]}"></span></span><span>${compact(r.actual)}</span></button>`).join('')}</div>`;const total=rows.reduce((s,r)=>s+r.actual,0);let acc=0;const gradient=rows.map((r,i)=>{const start=acc;acc+=r.actual/(total||1)*100;return `${colors[i%5]} ${start}% ${acc}%`;}).join(',');return `<div class="donut-layout"><div class="donut" style="background:conic-gradient(${gradient})" role="img" aria-label="Custos por categoria. Total ${money(total)}"><div class="donut-center">Total<strong>${compact(total)}</strong></div></div><div class="donut-legend">${rows.map((r,i)=>`<button data-drill="${esc(r.label)}"><span class="legend-dot" style="background:${colors[i%5]}"></span>${esc(r.label)}<b>${(r.actual/(total||1)*100).toFixed(0)}%</b></button>`).join('')}</div></div>`;}
function insight(d=dash()){const m=metrics(d),rows=group(selectRows(d),'category');const over=rows.filter(r=>r.actual>r.budget);if(!rows.length)return 'Nenhum registro corresponde aos filtros. Amplie o período ou selecione outra área.';return `${d.area==='Todas as áreas'?'As áreas selecionadas':d.area} ${m.delta>=0?'está':'está'} ${Math.abs(m.percent).toFixed(1).replace('.',',')}% ${m.delta>=0?'abaixo':'acima'} do orçamento. ${over.length?over.map(r=>r.label).join(' e ')+' ultrapassam o planejado.':'Todas as categorias estão dentro do planejado.'} ${rows[0].label} representa ${(rows[0].actual/(m.actual||1)*100).toFixed(0)}% do custo total.`;}
function chatPanel(d){const welcome=`Preparei uma visão dos custos de ${d.area.toLowerCase()} em ${periodLabel(d.period).toLowerCase()}.\n\n${insight(d)}\n\nVocê pode editar os gráficos ou pedir uma mudança por aqui.`;return `<aside class="chat-panel" aria-label="Assistente do dashboard"><div class="chat-head"><span class="ai-mini">${icon('spark')}</span><div><strong>Assistente Prometeu</strong><small>Respostas guiadas · demonstração</small></div><button class="icon-btn" data-action="toggle-chat" aria-label="Recolher assistente">${icon('close')}</button></div><div class="chat-messages" id="chat-messages"><div class="message"><div class="message-label">${icon('spark')} PROMETEU</div>${esc(welcome)}<div class="evidence">${icon('database')} <strong>${esc(sourceName())}</strong><br>${selectRows(d).length} registros · valores em BRL<br>Realizado = soma dos custos no recorte.<br>Projeção = média dos últimos 3 meses disponíveis.</div></div>${d.messages.map(m=>`<div class="message ${m.role==='user'?'user':''}">${m.role!=='user'?`<div class="message-label">${icon('spark')} PROMETEU</div>`:''}${esc(m.text)}</div>`).join('')}</div><div class="chat-quick"><button data-chat="Troque a evolução para linhas">Usar linhas</button><button data-chat="Explique o desvio do orçamento">Explicar o desvio</button><button data-chat="Crie uma apresentação">Gerar apresentação</button></div><form id="dashboard-chat" class="chat-form"><textarea id="dashboard-prompt" placeholder="Peça um ajuste no dashboard..." aria-label="Mensagem para o assistente"></textarea><div class="chat-form-bottom"><span>IA simulada · sem conexão externa</span><button class="send" aria-label="Enviar mensagem">${icon('send')}</button></div></form></aside>`;}
function dashboard(){const d=dash(),rows=sourceRows(),periods=[...new Set(rows.map(r=>r.date.slice(0,7)))].sort().reverse(),areas=[...new Set(rows.map(r=>r.area))];return `<div class="dashboard-topline"><a href="#dashboards">${icon('back')} Meus dashboards</a><span>/</span><span>${shared?'Snapshot compartilhado':'Salvo neste navegador'}</span><span class="tag blue">${d.source==='demo'?'Dados fictícios':'Dados locais'}</span></div><div class="page-heading"><div><button class="title-edit" data-action="rename-dashboard" title="Renomear dashboard"><h1>${esc(d.title)}</h1>${icon('edit')}</button><p>${esc(sourceName())} <span style="margin:0 5px">·</span> ${esc(periodLabel(d.period))}</p></div><div class="actions"><button class="btn" data-action="present">${icon('play')} Apresentar</button><button class="btn" data-action="export">${icon('download')} Exportar</button><button class="btn primary" data-action="share">${icon('share')} Compartilhar</button></div></div>${shared?'<div class="callout">Você está vendo uma cópia do dashboard no momento do compartilhamento. Alterações nesta visualização não afetam o original.</div>':''}<div class="filters"><label class="filter-control">${icon('clock')}<select id="period-filter" aria-label="Período">${periods.map(p=>`<option value="${p}" ${d.period===p?'selected':''}>${esc(periodLabel(p))}</option>`).join('')}</select></label><label class="filter-control">${icon('users')}<select id="area-filter" aria-label="Área">${['Todas as áreas',...areas].map(a=>`<option ${a===d.area?'selected':''}>${esc(a)}</option>`).join('')}</select></label><button class="filter-control" data-action="filters">${icon('filter')} ${d.categories.length?d.categories.length+' categorias':'Todos os dados'}⌄</button><button class="filter-control" data-action="source">${icon('database')} Fonte e data-base</button><span class="filter-note">${selectRows().length} registros no recorte</span>${!state.chatOpen?'<button class="btn" data-action="toggle-chat">Abrir assistente</button>':''}</div><div class="dashboard-layout ${!state.chatOpen?'chat-hidden':''}"><div class="dashboard-body">${kpis(d)}<div class="chart-grid"><article class="panel chart-card"><div class="panel-head"><div><h3>${esc(d.trendTitle)}</h3><div class="panel-subtitle">Últimos ${trendRows(d).length} meses disponíveis</div></div><button class="icon-btn" data-edit="trend" aria-label="Editar gráfico de evolução">${icon('edit')}</button></div><div class="legend"><span><i class="legend-dot"></i>Realizado</span>${d.showBudget?'<span><i class="legend-dot pale"></i>Orçamento</span>':''}</div>${trendChart(d)}<div class="chart-footer"><span>Valores em R$ · base mensal</span><span>Clique para filtrar</span></div></article><article class="panel chart-card"><div class="panel-head"><div><h3>${esc(d.mixTitle)}</h3><div class="panel-subtitle">Participação no realizado</div></div><button class="icon-btn" data-edit="mix" aria-label="Editar gráfico de categorias">${icon('edit')}</button></div>${mixChart(d)}<div class="chart-footer"><span>Clique na categoria para explorar</span></div></article></div><div class="insight-strip">${icon('spark')}<div><strong>Um ponto de atenção</strong><br>${esc(insight(d))}</div></div><article class="panel chart-card full"><div class="panel-head"><div><h3>${esc(d.tableTitle)}</h3><div class="panel-subtitle">Rastreie os valores que compõem sua análise</div></div><div class="actions"><button class="icon-btn" data-edit="table" aria-label="Renomear tabela">${icon('edit')}</button><button class="text-link" data-action="csv">Baixar CSV ${icon('download')}</button></div></div>${dataTable(group(selectRows(),'category'),true)}<div class="chart-footer"><span>Fonte: ${esc(sourceName())}</span><span>${d.source==='demo'?'Sem dados reais do SAP':'Processado neste navegador'}</span></div></article></div>${chatPanel(d)}</div>`;}
function library(){return `<div class="page-heading"><div><div class="eyebrow" style="margin-bottom:10px">SUAS DESCOBERTAS, ORGANIZADAS</div><h1>Meus dashboards</h1><p>Análises salvas neste navegador, prontas para continuar.</p></div><button class="btn primary" data-action="new">${icon('plus')} Nova análise</button></div><input class="control library-search" id="library-search" aria-label="Buscar dashboards" placeholder="Buscar pelo nome do dashboard..."><div class="library-grid" id="library-grid">${libraryCards('')}</div>`;}
function libraryCards(query){const list=state.dashboards.filter(d=>d.title.toLowerCase().includes(query.toLowerCase()));return list.length?list.map(d=>`<article class="recent-card library-card"><button class="card-open" data-open="${esc(d.id)}"><div class="recent-header"><span class="tag blue">${icon('chart')} ${d.source==='demo'?'Exemplo SAP':'Dados importados'}</span>${icon('arrow')}</div><h3>${esc(d.title)}</h3><p>${esc(periodLabel(d.period))} · ${esc(d.area)}</p><div class="mini-chart" aria-hidden="true">${[40,56,48,61,50,72,57,78].map(n=>`<span style="height:${n}%"></span>`).join('')}</div><div class="recent-meta"><span>${selectRows(d).length} registros</span><span>Salvo localmente</span></div></button><div class="actions"><button class="text-link" data-duplicate="${esc(d.id)}">Duplicar</button>${state.dashboards.length>1?`<button class="icon-btn" data-delete="${esc(d.id)}" aria-label="Excluir ${esc(d.title)}">${icon('trash')}</button>`:''}</div></article>`).join(''):'<div class="empty"><h3>Nenhum dashboard encontrado</h3><p>Tente buscar por outro nome.</p></div>';}
function sourcesPage(){return `<div class="page-heading"><div><h1>De onde vêm seus dados?</h1><p>Escolha a base certa para cada pergunta.</p></div><button class="btn primary" data-action="import">${icon('plus')} Importar arquivo</button></div><div class="grid-3"><article class="panel source-card"><div class="data-title-icon">${icon('database')}</div><h2>SAP S/4HANA</h2><p>Custos por área, categoria e período. Um conjunto fictício para explorar o Prometeu.</p><div class="source-details"><span class="tag blue">Demonstração</span><span class="tag">90 registros</span></div><button class="btn" data-action="sap">Ver conexão</button></article><article class="panel source-card"><div class="data-title-icon">${icon('file')}</div><h2>Seus arquivos</h2><p>Importe CSV, TXT delimitado ou Excel e veja os dados em um dashboard editável.</p><div class="source-details"><span class="tag">Processamento local</span></div><button class="btn" data-action="import">Escolher arquivo</button></article><article class="panel source-card"><div class="data-title-icon">${icon('layers')}</div><h2>Modelos de dados</h2><p>Medidas consistentes, dimensões compreensíveis e uma definição única para cada indicador.</p><div class="source-details"><span class="tag amber">Próxima etapa</span></div><button class="btn" data-action="model">Explorar modelo</button></article></div><div class="callout">${icon('shield')}<span>Arquivos são lidos no seu navegador. Este protótipo não envia os dados ao SAP nem a um serviço de IA. Se você criar um link de snapshot, os dados selecionados serão incluídos nesse link.</span></div><section class="panel"><div class="panel-head"><div><h2>Biblioteca de fontes</h2><p class="panel-subtitle">Disponíveis apenas neste dispositivo</p></div><button class="text-link" data-action="sample">Baixar CSV de exemplo ${icon('download')}</button></div><div class="table-wrap"><table><thead><tr><th>Fonte</th><th>Tipo</th><th>Registros</th><th>Status</th><th>Ação</th></tr></thead><tbody><tr><td>SAP · Custos e orçamento</td><td>Conjunto demonstrativo</td><td>${demoRows.length}</td><td><span class="tag blue">Fictício</span></td><td><button class="text-link" data-source-open="demo">Criar análise</button></td></tr>${state.sources.map(s=>`<tr><td>${esc(s.name)}</td><td>Arquivo local</td><td>${s.rows.length}</td><td><span class="tag green">Disponível</span></td><td><button class="text-link" data-source-open="${esc(s.id)}">Criar análise</button></td></tr>`).join('')}</tbody></table></div></section>`;}
function planning(){const d=dash(),m=metrics(d);return `<div class="page-heading"><div><h1>Antes de decidir, simule.</h1><p>Planejamento para ${esc(d.area)} · ${esc(periodLabel(d.period))}</p></div><button class="btn primary" data-action="save-scenario">${icon('plus')} Salvar cenário</button></div><div class="scenario-hero"><div><span class="eyebrow" style="color:#aebbef">CENÁRIOS QUE VOCÊ CONTROLA</span><h2 style="margin-top:10px">Pequenos ajustes. Novas possibilidades.</h2><p>Teste variações sobre o custo realizado. O cenário preserva os dados da análise original.</p></div><div><small style="color:#aebbef">Custo da base selecionada</small><div class="scenario-number">${compact(m.actual)}</div></div></div><div class="grid-2"><section class="panel scenario-controls"><div class="panel-head"><div><h2>Ajuste as premissas</h2><p class="panel-subtitle">Variação percentual sobre cada grupo de custos</p></div><button class="text-link" data-action="reset-scenario">Restaurar</button></div>${[['infra','Infraestrutura e licenças'],['people','Pessoas'],['services','Demais categorias']].map(([key,label])=>`<label for="scenario-${key}">${label}<strong id="value-${key}">${state.scenario[key]>0?'+':''}${state.scenario[key]}%</strong></label><input id="scenario-${key}" data-scenario="${key}" type="range" min="-30" max="30" step="1" value="${state.scenario[key]}" aria-label="Variação de ${label}">`).join('')}<div class="callout" style="font-size:12px">Simulação aritmética, sem previsão por IA. Não grava no SAP e não representa uma aprovação de orçamento.</div></section><section class="panel"><div class="panel-head"><div><h2>Impacto do cenário</h2><p class="panel-subtitle">O resultado muda a cada ajuste</p></div><span class="tag blue">What-if</span></div><div id="scenario-results">${scenarioResults()}</div></section></div><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Cenários salvos</h2><span class="tag">Neste navegador</span></div><div id="scenario-saved">${scenarioSaved()}</div></section>`;}
function scenarioMath(){const rows=selectRows(),base=totals(rows);let value=0;rows.forEach(r=>{const key=['Infraestrutura','Licenças'].includes(r.category)?'infra':r.category==='Pessoas'?'people':'services';value+=r.actual*(1+state.scenario[key]/100);});return {base:base.actual,budget:base.budget,value,delta:base.actual-value};}
function scenarioResults(){const v=scenarioMath(),max=Math.max(v.base,v.value,v.budget,1);return `<div style="font:750 38px Manrope,sans-serif;letter-spacing:-1px;color:var(--navy);margin-bottom:8px">${money(v.value)}</div><span class="tag ${v.delta>=0?'green':'amber'}">${v.delta>=0?'Economia':'Acréscimo'} de ${money(Math.abs(v.delta))}</span><div class="bar-list" style="margin:27px 0">${[['Atual',v.base,'#a6b4ed'],['Cenário',v.value,'#1b34c8'],['Orçamento',v.budget,'#d6ddf5']].map(([label,n,color])=>`<div class="bar-row"><span>${label}</span><span class="bar-track"><span style="width:${n/max*100}%;background:${color}"></span></span><span>${compact(n)}</span></div>`).join('')}</div><div class="scenario-total"><span>Saldo sobre orçamento</span><strong class="${v.budget-v.value<0?'danger-text':''}">${money(v.budget-v.value)}</strong></div>`;}
function scenarioSaved(){return state.scenarios.length?`<div class="table-wrap"><table><thead><tr><th>Cenário</th><th>Contexto</th><th>Base</th><th>Resultado</th><th>Economia</th></tr></thead><tbody>${state.scenarios.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.area)} · ${esc(periodLabel(s.period))}</td><td>${money(s.base)}</td><td>${money(s.value)}</td><td class="${s.delta>=0?'positive':'danger-text'}">${money(s.delta)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="notes">Ajuste as premissas e salve seu primeiro cenário para comparar decisões.</p>';}
function governance(){return `<div class="page-heading"><div><h1>Confiança em cada resposta.</h1><p>Proposta de governança para a versão corporativa do Prometeu.</p></div><span class="tag amber">Especificação · não implementada</span></div><div class="grid-3">${[['shield','Acesso por área','Cada pessoa consulta somente os centros de custo, empresas e dados que tem permissão para ver.'],['database','Rastreabilidade','Cada indicador mostra fonte, data de atualização, filtros e fórmula. A IA trabalha sobre definições aprovadas.'],['users','Colaboração controlada','Compartilhe com pessoas ou grupos. Defina visualização, edição, validade do acesso e histórico de alterações.']].map(([i,t,p])=>`<article class="panel"><div class="data-title-icon">${icon(i)}</div><h2>${t}</h2><p class="notes" style="margin-top:12px">${p}</p></article>`).join('')}</div><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Papéis e responsabilidades propostos</h2></div><div class="table-wrap"><table><thead><tr><th>Permissão</th><th>Leitor</th><th>Editor</th><th>Administrador</th></tr></thead><tbody>${[['Ver análises autorizadas','Sim','Sim','Sim'],['Criar e editar dashboards','Não','Sim','Sim'],['Compartilhar com grupos permitidos','Não','Sim','Sim'],['Gerenciar conexões e modelos','Não','Não','Sim'],['Aprovar orçamento','Papel específico','Papel específico','Papel específico']].map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><div class="callout">${icon('info')}<span>Neste protótipo, não existe autenticação interna, controle por linha nem envio de convites. O compartilhamento cria um snapshot nos parâmetros do link, sem restrição por destinatário.</span></div><section class="panel"><h2>Rastro da análise atual</h2><p class="notes" style="margin-top:12px">Fonte: ${esc(sourceName())}<br>Medida de custo: soma de “realizado”. Saldo: orçamento − realizado.<br>Filtros: ${esc(dash().area)}, ${esc(periodLabel(dash().period))}. Categorias: ${dash().categories.length?esc(dash().categories.join(', ')):'todas'}.<br>Projeção: média dos últimos 3 meses disponíveis até a data-base. Não é modelo preditivo.</p></section>`;}
function product(){return `<div class="page-heading"><div><h1>O Prometeu, além do protótipo.</h1><p>Interface simples. Profundidade disponível quando você precisar.</p></div></div><section class="product-intro"><span class="eyebrow" style="color:#abb9fa">PROPOSTA DE PRODUTO</span><h2>Uma conversa vira análise.<br>Uma análise vira uma decisão explicável.</h2><p>Comece perguntando. Explore a resposta. Ajuste os detalhes. Compartilhe a conclusão. A complexidade fica nos modelos de dados e nas permissões, sem sobrecarregar quem precisa decidir.</p></section><div class="grid-3">${[['01','Validar a experiência','Este protótipo',['Chat com intenções guiadas','Dashboards, filtros e edição','Importação de dados locais','Apresentação, PDF e cenários']],['02','Conectar com confiança','MVP de produção',['SAP S/4HANA via APIs autorizadas','SSO e acesso por centro de custo','IA sobre métricas homologadas','Compartilhamento autenticado']],['03','Expandir a profundidade','Evolução corporativa',['Modelagem, hierarquias e cálculos','Planejamento, versões e aprovações','Previsões e análise de influência','Agendamentos e colaboração']]].map(([n,t,phase,list])=>`<article class="panel roadmap-card"><div class="step">${n}</div><h2>${t}</h2><p>${phase}</p><ul>${list.map(x=>`<li>${x}</li>`).join('')}</ul></article>`).join('')}</div><section class="panel" style="margin-top:24px"><div class="panel-head"><div><h2>Referência funcional: SAP Analytics Cloud</h2><p class="panel-subtitle">Mapa por família de recursos. Não é uma declaração de equivalência completa.</p></div></div><div class="table-wrap"><table><thead><tr><th>Família</th><th>Experiência no Prometeu</th><th>Este protótipo</th><th>Produção</th></tr></thead><tbody>${[['BI e stories','Dashboards editáveis, filtros, detalhe e apresentação','Interativo','Ampliar visuais e interações'],['Data Analyzer','Exploração tabular de métricas e dimensões','Tabela e filtros','Pivot, hierarquias e drill-through'],['Integração e modelagem','SAP, arquivos, semântica e qualidade','Arquivos reais; SAP simulado','Conectores, relações e atualização'],['Analytics aumentada','Perguntas, explicações e sugestões','Respostas guiadas','IA validada e rastreável'],['Planejamento','Cenários, versões, orçamento e aprovação','Simulação aritmética','Write-back, alocações, workflow'],['Predição','Projeções, influência e risco','Média móvel simples','Modelos, backtesting e incerteza'],['Colaboração e distribuição','Links, comentários, exportação e agenda','Snapshot, HTML e impressão PDF','Permissões, comentários e agendas'],['Governança e extensibilidade','SSO, acesso por linha, auditoria e APIs','Proposta de experiência','Backend, observabilidade e SDK']].map(r=>`<tr>${r.map((x,i)=>`<td${i===0?' style="font-weight:600"':''}>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="notes" style="margin-top:18px">Referências: <a href="https://www.sap.com/products/cloud-analytics.html" target="_blank" rel="noreferrer">SAP Analytics Cloud</a> e <a href="https://help.sap.com/docs/SAP_ANALYTICS_CLOUD/00f68c2e08b941f081002fd3691d86a7/449cc17118304d73b2d50d562eff50a5.html" target="_blank" rel="noreferrer">documentação SAP</a>. Paridade com Power BI e SAC exige inventário detalhado por versão e licença.</p></section><section class="panel" style="margin-top:24px"><h2>Quatro decisões que tornam o produto melhor</h2><div class="grid-2" style="margin-top:20px">${[['Pergunte antes de calcular','Se “custo” puder significar realizado, comprometido ou pago, a IA confirma a definição.'],['Mostre de onde veio','Fonte, período, atualização e cálculo ficam disponíveis em cada gráfico.'],['Deixe o controle com a pessoa','Toda sugestão pode ser editada, desfeita e salva como nova versão.'],['Separe análise de ação','Consultar dados e publicar um orçamento exigem permissões e aprovações diferentes.']].map(([t,p])=>`<div><h3>${t}</h3><p class="notes" style="margin-top:6px">${p}</p></div>`).join('')}</div></section>`;}
function render(){const route=location.hash.slice(1).split('?')[0]||'inicio';$('#crumb').textContent=({inicio:'Assistente',dashboards:'Meus dashboards',dashboard:'Visão de custos',dados:'Fontes de dados',planejamento:'Planejamento',governanca:'Acesso e governança',produto:'Visão do produto'})[route]||'Assistente';$$('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===route||(route==='dashboard'&&a.dataset.route==='dashboards')));$('#main').innerHTML=({inicio:home,dashboards:library,dashboard,dados:sourcesPage,planejamento:planning,governanca:governance,produto:product}[route]||home)();$('#dashboard-count').textContent=state.dashboards.length;hydrate();$('#sidebar').classList.remove('open');if($('#chat-messages'))$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;}
function navigate(route){window.scrollTo?.(0,0);if(location.hash==='#'+route)render();else location.hash=route;}
function changed(){dash().updated=new Date().toISOString();persist();render();}
function openDashboard(id){if(id)state.current=id;persist();navigate('dashboard');}
function createDashboard(source='demo',prompt=''){const rows=source==='demo'?demoRows:state.sources.find(s=>s.id===source)?.rows;if(!rows?.length)return toast('Importe uma fonte com dados válidos primeiro.');const d={...defaultDashboard(),id:'d'+Date.now(),source,period:[...new Set(rows.map(r=>r.date.slice(0,7)))].sort().at(-1),area:rows[0].area};if(/opera/i.test(prompt)&&rows.some(r=>r.area==='Operações'))d.area='Operações';if(/comercial|vendas/i.test(prompt)&&rows.some(r=>r.area==='Comercial'))d.area='Comercial';if(/todas as áreas|todas as areas/i.test(prompt))d.area='Todas as áreas';for(const [name,month] of [['abril','2026-04'],['maio','2026-05'],['junho','2026-06'],['julho','2026-07'],['agosto','2026-08'],['setembro','2026-09']])if(normalized(prompt).includes(name)&&rows.some(r=>r.date.startsWith(month)))d.period=month;d.title='Visão de custos · '+d.area;if(source!=='demo')d.title='Análise · '+(state.sources.find(s=>s.id===source)?.name||'Arquivo');if(prompt)d.messages.push({role:'user',text:prompt});state.dashboards.push(d);state.current=d.id;persist();openDashboard();}
function editChart(kind){const d=dash(),key=kind==='trend'?'trend':kind==='mix'?'mix':'table';const choices=kind==='trend'?[['bar','Barras agrupadas'],['line','Linhas'],['table','Tabela']]:[['donut','Rosca'],['bar','Barras horizontais'],['table','Tabela']];showModal(kind==='table'?'Editar tabela':'Editar visualização',`<p class="modal-description">Escolha como contar essa parte da história.</p><form id="edit-chart" data-kind="${key}"><label class="form-field">Título<input name="title" required maxlength="100" value="${esc(d[key+'Title'])}"></label>${kind!=='table'?`<label class="form-field">Tipo de visualização<select name="type">${choices.map(([v,t])=>`<option value="${v}" ${d[key+'Type']===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="source-preview"><strong>Medida:</strong> soma do realizado<br><strong>Dimensão:</strong> ${kind==='trend'?'mês':'categoria'}<br><strong>Fonte:</strong> ${esc(sourceName())}</div>`:''}${kind==='trend'?`<label class="switch-row"><input type="checkbox" name="budget" ${d.showBudget?'checked':''}> Exibir orçamento como comparação</label>`:''}<div class="modal-actions"><button class="btn" type="button" data-action="close">Cancelar</button><button class="btn primary">Salvar alterações</button></div></form>`);}
function filterModal(){const d=dash(),cats=[...new Set(sourceRows().map(r=>r.category))];showModal('Escolha os dados',`<p class="modal-description">Selecione as categorias que entram em todos os indicadores.</p><form id="filter-form"><div class="checklist">${cats.map(c=>`<label><input name="category" type="checkbox" value="${esc(c)}" ${!d.categories.length||d.categories.includes(c)?'checked':''}>${esc(c)}</label>`).join('')}</div><div id="filter-error"></div><div class="modal-actions"><button class="btn" type="button" data-action="clear-filters">Restaurar todos</button><button class="btn primary">Aplicar filtros</button></div></form>`);}
function sourceModal(){const d=dash();showModal('Fonte e data-base',`<p class="modal-description">Escolha a origem da análise e revise o período no filtro do dashboard.</p><form id="source-form"><label class="form-field">Fonte de dados<select name="source"><option value="demo">SAP S/4HANA · demonstrativo</option>${state.sources.map(s=>`<option value="${esc(s.id)}" ${d.source===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><div class="source-preview"><strong>SAP neste protótipo</strong><br>90 registros fictícios, de abril a setembro de 2026. Não há conexão com um ambiente SAP real.</div><button class="text-link" type="button" data-action="import" style="margin-top:17px">${icon('plus')} Importar CSV, texto ou Excel</button><div class="modal-actions"><button class="btn primary">Usar esta fonte</button></div></form>`);}
function drill(category){const rows=selectRows().filter(r=>r.category===category),t=totals(rows);showModal(category,`<p class="modal-description">${esc(dash().area)} · ${esc(periodLabel(dash().period))}</p><div class="source-preview">Realizado: <strong>${money(t.actual)}</strong><br>Orçamento: <strong>${money(t.budget)}</strong><br>Saldo: <strong>${money(t.budget-t.actual)}</strong><br>Origem: ${esc(sourceName())}</div><div class="table-wrap" style="margin-top:18px"><table><thead><tr><th>Data-base</th><th>Área</th><th class="number">Realizado</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.area)}</td><td class="number">${money(r.actual)}</td></tr>`).join('')}</tbody></table></div><div class="modal-actions"><button class="btn" data-action="close">Voltar</button><button class="btn primary" data-filter-category="${esc(category)}">Filtrar só esta categoria</button></div>`);}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function csvText(rows){const quote=v=>'"'+String(v).replace(/"/g,'""')+'"';return '\uFEFFdata;area;categoria;realizado;orcado\r\n'+rows.map(r=>[r.date,r.area,r.category,r.actual.toFixed(2).replace('.',','),r.budget.toFixed(2).replace('.',',')].map(quote).join(';')).join('\r\n');}
function exportModal(){showModal('Leve sua análise com você',`<p class="modal-description">A exportação usa o dashboard com os filtros atuais.</p><div class="checklist"><button class="btn" data-action="pdf">${icon('file')} Dashboard em PDF</button><button class="btn" data-action="html">${icon('play')} Apresentação HTML independente</button><button class="btn" data-action="csv">${icon('table')} Dados filtrados em CSV</button></div><p class="notes">PDF: abre a impressão do navegador. Escolha “Salvar como PDF”. A apresentação HTML funciona sem internet e inclui 3 slides navegáveis.</p>`);}
function shareModal(){const d=dash();showModal('Compartilhar uma descoberta',`<p class="modal-description">Crie um link com uma cópia dos dados e da configuração atual.</p><div class="source-preview"><strong>${esc(d.title)}</strong><br>${esc(d.area)} · ${esc(periodLabel(d.period))}<br>O snapshot inclui o histórico usado no gráfico de evolução.</div><div class="callout">${icon('info')}<span>Protótipo: qualquer pessoa com o link e acesso ao site poderá ler os dados incluídos. Não há permissão por destinatário nem atualização automática.</span></div><button class="btn primary" data-action="generate-link">${icon('link')} Gerar link de snapshot</button><div id="share-result"></div>`);}
function generateLink(){if(location.protocol==='file:'){toast('Abra o protótipo em um endereço web para gerar links.');return;}const d=dash(),rows=selectRows(d,true).filter(r=>r.date.slice(0,7)<=d.period),payload={dashboard:pickDashboard(d),rows};const encoded=btoa(unescape(encodeURIComponent(JSON.stringify(payload))));const url=location.origin+location.pathname+'#dashboard?snapshot='+encodeURIComponent(encoded);if(url.length>45000){$('#share-result').innerHTML='<div class="error">Este recorte é grande demais para um link de protótipo. Reduza os filtros ou exporte a apresentação HTML.</div>';return;}$('#share-result').innerHTML=`<label class="form-field">Link do snapshot<input id="share-url" readonly value="${esc(url)}"></label><button class="btn" data-action="copy-link">Copiar link</button><p class="notes" style="margin-top:10px">O link abre uma cópia independente. Ele não concede acesso a outros dashboards.</p>`;}
async function copyLink(){const input=$('#share-url');try{await navigator.clipboard.writeText(input.value);toast('Link copiado.');}catch{input.select();toast('Selecione e copie o link com Ctrl+C.');}}
function normalized(t){return t.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');}
async function askHome(prompt){if(!prompt.trim())return toast('Digite uma pergunta ou escolha uma sugestão.');if(/simul|cenario|redu[cç]/i.test(prompt)){navigate('planejamento');if(/10/.test(prompt)){state.scenario={infra:-10,people:-10,services:-10};persist();render();}return;}const p=normalized(prompt);if(!/custo|orcamento|dashboard|realizado|despesa|tecnologia|operac|comercial/.test(p)){$('#home-result').innerHTML='<div class="callout">O chat deste protótipo usa exemplos guiados. Experimente “custos da minha área”, “realizado × orçamento” ou “simular cenário”.</div>';return;}$('#home-result').innerHTML='<div class="loading-box"><p>Organizando os dados demonstrativos e preparando sua análise…</p><div class="loading-line"></div></div>';$('#home-chat button[type=submit]').disabled=true;await new Promise(r=>setTimeout(r,700));createDashboard(dash().source,prompt);}
function chatAction(text){if(!text.trim())return;const d=dash(),p=normalized(text);d.messages.push({role:'user',text});let answer='',present=false;if(/apresenta/.test(p)){answer='Organizei uma apresentação com visão geral, evolução e composição dos custos. Use as setas para navegar ou exporte em HTML.';present=true;}else if(/renome|titulo|nome/.test(p)&&/para/.test(p)){const title=text.split(/para\s+/i).slice(1).join('para ').replace(/^["“']|["”']$/g,'').trim();if(title){if(/evoluc/.test(p))d.trendTitle=title.slice(0,100);else if(/categoria|rosca/.test(p))d.mixTitle=title.slice(0,100);else d.title=title.slice(0,100);answer='Título atualizado. A alteração foi aplicada à análise.';}}else if(/linha/.test(p)){d.trendType='line';answer='Troquei a evolução dos custos para linhas, preservando os dados e os filtros.';}else if(/barra/.test(p)){if(/categoria|rosca/.test(p))d.mixType='bar';else d.trendType='bar';answer='Gráfico atualizado para barras. Você também pode ajustar o título pelo ícone de edição.';}else if(/rosca|pizza/.test(p)){d.mixType='donut';answer='A composição dos custos agora aparece em rosca.';}else if(/tabela/.test(p)){d.trendType='table';answer='A evolução agora mostra os valores em tabela.';}else if(/explique|desvio|porque|por que|insight/.test(p)){answer=insight(d)+'\n\nO saldo é calculado como orçamento menos realizado. Estes dados não explicam a causa do desvio; para isso, a versão conectada deverá consultar lançamentos e contexto operacional.';}else if(/operac|comercial|tecnologia|agosto|setembro|julho|todas as areas/.test(p)){let applied=false;for(const a of ['Tecnologia','Operações','Comercial','Todas as áreas'])if(p.includes(normalized(a))&&(a==='Todas as áreas'||sourceRows().some(r=>r.area===a))){d.area=a;applied=true;}for(const [n,v] of [['agosto','2026-08'],['setembro','2026-09'],['julho','2026-07']])if(p.includes(n)&&sourceRows().some(r=>r.date.startsWith(v))){d.period=v;applied=true;}answer=applied?'Filtros atualizados. '+insight(d):'Esse recorte não está disponível na fonte atual. Use os filtros para consultar os períodos e áreas existentes.';}else if(/previs|projec/.test(p)){answer=`A projeção é ${money(metrics(d).forecast)}, calculada pela média dos últimos ${Math.min(3,trendRows(d).length)} meses disponíveis. É uma referência aritmética, não uma previsão estatística treinada.`;}else if(/pdf|export/.test(p)){answer='Use Exportar para salvar o dashboard em PDF, os dados em CSV ou a apresentação em HTML.';}else answer='Neste protótipo, consigo trocar gráficos, explicar desvios, filtrar áreas e meses, renomear títulos e gerar a apresentação. Experimente “troque para linhas” ou “explique o desvio”. Uma IA de uso geral entra na etapa de integração.';if(!answer)answer='Informe o novo título depois de “para”.';d.messages.push({role:'assistant',text:answer});changed();if(present)startPresentation();}
function validateRows(rows){if(!Array.isArray(rows)||!rows.length)throw Error('O arquivo não contém registros.');if(rows.length>5000)throw Error('O protótipo aceita até 5.000 registros por arquivo.');return rows.map((r,i)=>{const date=String(r.date||'').trim(),area=String(r.area||'').trim(),category=String(r.category||'').trim(),actual=Number(r.actual),budget=Number(r.budget);if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||isNaN(Date.parse(date+'T12:00:00'))||new Date(date+'T12:00:00').toISOString().slice(0,10)!==date)throw Error(`Linha ${i+2}: use uma data válida no formato AAAA-MM-DD.`);if(!area||!category||area.length>100||category.length>100)throw Error(`Linha ${i+2}: área e categoria são obrigatórias (até 100 caracteres).`);if(!Number.isFinite(actual)||!Number.isFinite(budget)||actual<0||budget<0)throw Error(`Linha ${i+2}: realizado e orçado devem ser números positivos ou zero.`);return {date,area,category,actual,budget};});}
function parseDelimited(text){text=text.replace(/^\uFEFF/,'');const line=text.split(/\r?\n/)[0],delimiter=line.includes('\t')?'\t':line.includes(';')?';':',';const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===delimiter&&!quoted){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(v=>v.trim()))rows.push(row);row=[];field='';}else field+=c;}if(quoted)throw Error('Há aspas não fechadas no arquivo.');row.push(field);if(row.some(v=>v.trim()))rows.push(row);return rows;}
function rowsFromTable(table){if(table.length<2)throw Error('Inclua um cabeçalho e pelo menos uma linha de dados.');const headers=table[0].map(h=>normalized(String(h)).trim());const required=['data','area','categoria','realizado','orcado'],ix=required.map(h=>headers.indexOf(h));if(ix.some(i=>i<0))throw Error('Colunas necessárias: data, area, categoria, realizado, orcado. Baixe o arquivo de exemplo.');const num=v=>{if(typeof v==='number')return v;let s=String(v??'').trim().replace(/R\$|\s/g,'');if(!s)return NaN;if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');return Number(s);};return validateRows(table.slice(1).filter(r=>r.some(v=>String(v).trim())).map(r=>({date:String(r[ix[0]]??'').trim(),area:r[ix[1]],category:r[ix[2]],actual:num(r[ix[3]]),budget:num(r[ix[4]])})));}
let pendingImport=null;
function importModal(){pendingImport=null;if($('#modal').open)$('#modal').close();showModal('Importar seus dados',`<p class="modal-description">CSV, TXT delimitado ou XLSX. Até 5.000 linhas e 3 MB. A primeira planilha do Excel será usada.</p><label class="upload-zone">${icon('download')}<strong>Escolha um arquivo no seu computador</strong><small>Leitura e prévia no próprio navegador</small><input id="import-file" type="file" accept=".csv,.txt,.xlsx" style="display:block;max-width:100%;margin:15px auto 0;font-size:12px"></label><div class="source-preview" style="margin-top:15px">Colunas: <code>data, area, categoria, realizado, orcado</code><br><small>Data no formato AAAA-MM-DD. Excel: células numéricas para valores e texto para data.</small></div><button class="text-link" data-action="sample" style="margin-top:13px">Baixar CSV de exemplo</button><div id="import-preview" aria-live="polite"></div>`);}
async function readImport(file){pendingImport=null;if(!file)return;if(file.size>3*1024*1024){$('#import-preview').innerHTML='<div class="error">O arquivo excede 3 MB.</div>';return;}$('#import-preview').innerHTML='<p class="notes" style="margin-top:16px">Lendo arquivo…</p>';try{let table;if(/\.xlsx$/i.test(file.name)){if(!window.XLSX)throw Error('O leitor Excel não está disponível. Salve sua planilha como CSV.');const book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false});table=XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{header:1,raw:true,defval:''});const dateIndex=table[0]?.findIndex(h=>normalized(String(h))==='data');if(dateIndex>=0)table.slice(1).forEach(r=>{if(typeof r[dateIndex]==='number'){const date=XLSX.SSF.parse_date_code(r[dateIndex]);if(date)r[dateIndex]=`${date.y}-${String(date.m).padStart(2,'0')}-${String(date.d).padStart(2,'0')}`;}});}else table=parseDelimited(await file.text());const rows=rowsFromTable(table);pendingImport={name:file.name,rows};$('#import-preview').innerHTML=`<div class="callout">${icon('check')} ${rows.length} registros válidos. Total realizado: ${money(totals(rows).actual)}.</div><div class="table-wrap"><table><thead><tr><th>Área</th><th>Categoria</th><th>Realizado</th></tr></thead><tbody>${rows.slice(0,3).map(r=>`<tr><td>${esc(r.area)}</td><td>${esc(r.category)}</td><td>${money(r.actual)}</td></tr>`).join('')}</tbody></table></div><div class="modal-actions"><button class="btn primary" data-action="confirm-import">Criar dashboard com este arquivo</button></div>`;}catch(e){$('#import-preview').innerHTML=`<div class="error">${esc(e.message)}</div>`;}}
function confirmImport(){if(!pendingImport)return;const s={...pendingImport,id:'s'+Date.now()};state.sources.push(s);$('#modal').close();createDashboard(s.id);pendingImport=null;toast('Arquivo importado. Seu dashboard está pronto.');}
let slideIndex=0;
function slideMarkup(index){const d=dash(),m=metrics(d);if(index===0)return `<span class="eyebrow">01 / VISÃO EXECUTIVA</span><h1>${esc(d.title)}</h1><p>${esc(d.area)} · ${esc(periodLabel(d.period))}</p>${kpis(d)}<div class="insight-strip">${icon('spark')}<div>${esc(insight(d))}</div></div><div class="slide-source">${esc(sourceName())} · apresentação de demonstração</div>`;if(index===1)return `<span class="eyebrow">02 / EVOLUÇÃO</span><h1>${esc(d.trendTitle)}</h1><p>Realizado e orçamento ao longo dos meses disponíveis.</p><div class="legend" style="margin-top:20px"><span><i class="legend-dot"></i>Realizado</span>${d.showBudget?'<span><i class="legend-dot pale"></i>Orçamento</span>':''}</div>${trendChart({...d,trendType:d.trendType==='table'?'bar':d.trendType})}<div class="slide-source">Projeção para o próximo mês: ${money(m.forecast)}. Média aritmética dos últimos 3 meses disponíveis.</div>`;return `<span class="eyebrow">03 / COMPOSIÇÃO E PRÓXIMOS PASSOS</span><h1>${esc(d.mixTitle)}</h1>${mixChart({...d,mixType:'bar'})}<div class="insight-strip">${icon('spark')}<div>Revise as categorias acima do orçamento e valide as causas nos lançamentos de origem antes de definir uma ação.</div></div><div class="slide-source">${esc(sourceName())} · período ${esc(periodLabel(d.period))}</div>`;}
function startPresentation(){if($('#modal').open)$('#modal').close();slideIndex=0;$('#presentation').hidden=false;document.body.classList.add('presentation-mode');$('.app').inert=true;$('#sidebar').inert=true;renderSlide();$('#presentation [data-action="exit-presentation"]').focus();}
function renderSlide(){const el=$('#presentation');el.className='presentation-overlay';el.setAttribute('role','dialog');el.setAttribute('aria-modal','true');el.setAttribute('aria-label','Apresentação do dashboard');el.innerHTML=`<div class="presentation-toolbar"><strong>prometeu <span style="font-weight:400;color:#8d9bcf">/ apresentação</span></strong><div class="actions"><button class="btn" data-action="html">${icon('download')} Baixar HTML</button><button class="btn" data-action="exit-presentation">${icon('close')} Sair</button></div></div><section class="slide" aria-live="polite">${slideMarkup(slideIndex)}</section><div class="slide-controls"><button class="btn" data-action="prev-slide" ${slideIndex===0?'disabled':''}>${icon('back')} Anterior</button><span>${slideIndex+1} / 3</span><button class="btn" data-action="next-slide" ${slideIndex===2?'disabled':''}>Próximo ${icon('arrow')}</button></div><div class="slide-footer"><span>${esc(sourceName())}</span><span>← → para navegar · Esc para sair</span></div>`;}
function exitPresentation(){$('#presentation').hidden=true;$('#presentation').className='';document.body.classList.remove('presentation-mode');$('.app').inert=false;$('#sidebar').inert=false;$('[data-action="present"]')?.focus();}
function exportHTML(){const css=`*{box-sizing:border-box}body{margin:0;background:#0b1354;color:#171d3c;font:16px/1.6 system-ui,sans-serif}header,nav{padding:18px 5%;display:flex;gap:20px;justify-content:space-between;color:white}button{background:#1b34c8;color:#fff;border:1px solid #8998df;padding:10px 20px;border-radius:7px;cursor:pointer}section.slide{background:#fff;border-radius:14px;margin:15px 5%;padding:4%;min-height:70vh}.slide[hidden]{display:none}.eyebrow{color:#1b34c8;font-size:13px;letter-spacing:2px}h1{font-size:38px;color:#0b1354;line-height:1.2}.kpi-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:25px 0}.kpi{border:1px solid #e0e5f3;border-radius:8px;padding:20px}.kpi-value{font-size:27px;font-weight:700}.kpi-label,.kpi-foot,.slide-source{font-size:12px;color:#65708d}.icon{width:20px;height:20px;stroke:currentColor;fill:none;stroke-width:1.6;display:inline-block;vertical-align:middle}.plot{width:100%;height:330px}.plot text{fill:#65708d;font-size:12px}.gridline{stroke:#e4e8f3;stroke-dasharray:3 4}.legend{display:flex;gap:20px;font-size:12px}.legend-dot{display:inline-block;width:8px;height:8px;background:#1b34c8;margin-right:6px}.legend-dot.pale{background:#d7def9}.insight-strip{background:#eef1ff;padding:20px;border-radius:9px;margin:25px 0;display:flex;gap:12px}.bar-row{border:0;background:white;display:grid;grid-template-columns:150px 1fr 100px;width:100%;text-align:left;gap:20px;align-items:center;margin:20px 0;color:#374165;font-size:14px}.bar-track{background:#f0f3fb;height:30px;border-radius:4px}.bar-track span{display:block;height:100%;border-radius:4px}.slide-source{margin-top:20px}@media(max-width:650px){h1{font-size:26px}.kpi-grid{grid-template-columns:1fr 1fr}.kpi{padding:12px}.kpi-value{font-size:21px}.bar-row{grid-template-columns:90px 1fr 80px;gap:8px;font-size:11px}}@media print{@page{size:A4 landscape}body{background:white}header,nav{display:none}section.slide,section.slide[hidden]{display:block!important;break-after:page;margin:0;min-height:0;padding:20px}}`;const slides=[0,1,2].map((n)=>`<section class="slide" ${n?'hidden':''}>${slideMarkup(n).replace(/data-drill="[^"]*"/g,'')}</section>`).join('');const html=`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(dash().title)} · Prometeu</title><style>${css}</style><body><header><strong>prometeu / ${esc(dash().title)}</strong><span>Snapshot · ${esc(periodLabel(dash().period))}</span></header>${slides}<nav><button id="prev">← Anterior</button><span id="count">1 / 3</span><button id="next">Próximo →</button></nav><script>let n=0;const slides=[...document.querySelectorAll('.slide')];function move(v){n=Math.max(0,Math.min(2,n+v));slides.forEach((s,i)=>s.hidden=i!==n);document.getElementById('count').textContent=(n+1)+' / 3';document.getElementById('prev').disabled=n===0;document.getElementById('next').disabled=n===2;}document.getElementById('prev').onclick=()=>move(-1);document.getElementById('next').onclick=()=>move(1);document.addEventListener('keydown',e=>{if(e.key==='ArrowRight')move(1);if(e.key==='ArrowLeft')move(-1)});move(0);<\/script></body></html>`;download('prometeu-apresentacao.html',html,'text/html;charset=utf-8');toast('Apresentação HTML exportada.');}
const actions={new:()=>navigate('inicio'),'open-dashboard':()=>openDashboard(),'open-example':()=>{const example=state.dashboards.find(d=>d.id==='demo');if(example)openDashboard('demo');else createDashboard('demo');},menu:()=>$('#sidebar').classList.toggle('open'),close:()=>$('#modal').close(),help:()=>showModal('Como explorar o Prometeu',`<p class="modal-description">Comece por uma pergunta ou abra o dashboard de exemplo.</p><div class="notes">1. Peça uma análise dos custos no assistente.<br>2. Troque o período, a área e as categorias.<br>3. Selecione um gráfico e edite no painel Propriedades.<br>4. Converse com o assistente do dashboard.<br>5. Apresente, exporte ou gere um snapshot.<br><br>Dados do SAP e respostas da IA são demonstrativos. CSV, TXT e Excel são processados localmente.</div><div class="modal-actions"><button class="btn primary" data-action="close">Começar</button></div>`),source:sourceModal,filters:filterModal,'clear-filters':()=>{dash().categories=[];$('#modal').close();changed();},'toggle-chat':()=>{state.chatOpen=!state.chatOpen;persist();render();},'rename-dashboard':()=>showModal('Renomear dashboard',`<form id="rename-form"><label class="form-field">Nome da análise<input name="title" required maxlength="100" value="${esc(dash().title)}"></label><div class="modal-actions"><button class="btn primary">Salvar nome</button></div></form>`),export:exportModal,pdf:()=>{$('#modal').close();navigate('dashboard');setTimeout(()=>window.print(),120);},csv:()=>{download('prometeu-dados.csv',csvText(selectRows()),'text/csv;charset=utf-8');toast('Dados do recorte exportados.');},sample:()=>download('prometeu-exemplo.csv',csvText(demoRows.filter(r=>r.area==='Tecnologia')),'text/csv;charset=utf-8'),share:shareModal,'generate-link':generateLink,'copy-link':copyLink,import:importModal,'confirm-import':confirmImport,present:startPresentation,html:exportHTML,'exit-presentation':exitPresentation,'prev-slide':()=>{slideIndex=Math.max(0,slideIndex-1);renderSlide();},'next-slide':()=>{slideIndex=Math.min(2,slideIndex+1);renderSlide();},'reset-scenario':()=>{state.scenario={infra:0,people:0,services:0};persist();render();},'save-scenario':()=>showModal('Salvar cenário',`<form id="save-scenario-form"><label class="form-field">Nome do cenário<input name="title" required maxlength="100" value="Cenário ${state.scenarios.length+1}"></label><p class="notes">Resultado: ${money(scenarioMath().value)}. Salvo apenas neste navegador.</p><div class="modal-actions"><button class="btn primary">Salvar cenário</button></div></form>`),sap:()=>showModal('Conexão SAP · demonstração',`<p class="modal-description">Nenhuma credencial real é necessária para explorar este protótipo.</p><div class="source-preview"><strong>Origem prevista:</strong> SAP S/4HANA<br><strong>Domínio:</strong> custos e orçamento<br><strong>Modelo:</strong> mês, área, categoria, realizado e orçado<br><strong>Status atual:</strong> conjunto fictício local</div><p class="notes" style="margin-top:18px">Para produção: validar a versão do SAP, as APIs/CDS Views liberadas, SSO, permissões por centro de custo e estratégia de atualização. A IA deve consultar modelos autorizados pelo backend.</p><div class="modal-actions"><button class="btn primary" data-source-open="demo">Explorar dados de exemplo</button></div>`),model:()=>showModal('Modelo de custos',`<div class="source-preview"><strong>Dimensões:</strong> data, área, categoria.<br><strong>Medidas:</strong> realizado, orçado.<br><strong>Saldo:</strong> Σ orçado − Σ realizado.<br><strong>Participação:</strong> realizado da categoria / total filtrado.<br><strong>Projeção:</strong> média de até 3 meses disponíveis.</div><p class="notes" style="margin-top:18px">Próxima etapa: relacionamentos, hierarquias, medidas calculadas, calendário fiscal, moeda e dicionário de negócios.</p>`)};
document.addEventListener('click',e=>{const b=e.target.closest('button,a,[data-month]');if(!b)return;const a=b.dataset.action;if(a&&actions[a])actions[a]();if(b.dataset.prompt)askHome(b.dataset.prompt);if(b.dataset.chat)chatAction(b.dataset.chat);if(b.dataset.open)openDashboard(b.dataset.open);if(b.dataset.edit)editChart(b.dataset.edit);if(b.dataset.drill)drill(b.dataset.drill);if(b.dataset.month){dash().period=b.dataset.month;changed();}if(b.dataset.filterCategory){dash().categories=[b.dataset.filterCategory];$('#modal').close();changed();}if(b.dataset.sourceOpen){if($('#modal').open)$('#modal').close();createDashboard(b.dataset.sourceOpen);}if(b.dataset.duplicate){const d=state.dashboards.find(x=>x.id===b.dataset.duplicate);const copy=JSON.parse(JSON.stringify(d));copy.id='d'+Date.now();copy.title+=' · cópia';state.dashboards.push(copy);persist();render();toast('Cópia criada.');}if(b.dataset.delete){const id=b.dataset.delete;showModal('Excluir dashboard?',`<p class="modal-description">Esta ação remove apenas a cópia salva neste navegador.</p><div class="modal-actions"><button class="btn" data-action="close">Cancelar</button><button class="btn danger" data-confirm-delete="${esc(id)}">Excluir dashboard</button></div>`);}if(b.dataset.confirmDelete){state.dashboards=state.dashboards.filter(x=>x.id!==b.dataset.confirmDelete);if(state.current===b.dataset.confirmDelete)state.current=state.dashboards[0].id;persist();$('#modal').close();render();}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,fd=new FormData(f);if(f.id==='home-chat')askHome($('#home-prompt').value);if(f.id==='dashboard-chat')chatAction($('#dashboard-prompt').value);if(f.id==='edit-chart'){const k=f.dataset.kind;dash()[k+'Title']=String(fd.get('title')).trim()||'Sem título';if(k!=='table')dash()[k+'Type']=fd.get('type');if(k==='trend')dash().showBudget=fd.has('budget');$('#modal').close();changed();toast('Visualização atualizada.');}if(f.id==='rename-form'){dash().title=String(fd.get('title')).trim()||'Minha análise';$('#modal').close();changed();}if(f.id==='filter-form'){const categories=fd.getAll('category');if(!categories.length){$('#filter-error').innerHTML='<div class="error">Selecione ao menos uma categoria.</div>';return;}dash().categories=categories;$('#modal').close();changed();}if(f.id==='source-form'){const id=fd.get('source'),rows=id==='demo'?demoRows:state.sources.find(s=>s.id===id).rows;dash().source=id;dash().period=rows.map(r=>r.date.slice(0,7)).sort().at(-1);dash().area=rows[0].area;dash().categories=[];dash().messages=[];$('#modal').close();changed();toast('Fonte atualizada.');}if(f.id==='save-scenario-form'){state.scenarios.push({name:String(fd.get('title')).trim()||'Cenário',...scenarioMath(),area:dash().area,period:dash().period,assumptions:{...state.scenario}});persist();$('#modal').close();render();toast('Cenário salvo neste navegador.');}});
document.addEventListener('change',e=>{if(e.target.id==='period-filter'){dash().period=e.target.value;changed();}if(e.target.id==='area-filter'){dash().area=e.target.value;changed();}if(e.target.id==='import-file')readImport(e.target.files[0]);});
document.addEventListener('input',e=>{if(e.target.id==='library-search')$('#library-grid').innerHTML=libraryCards(e.target.value);if(e.target.dataset.scenario){const k=e.target.dataset.scenario;state.scenario[k]=Number(e.target.value);$('#value-'+k).textContent=(state.scenario[k]>0?'+':'')+state.scenario[k]+'%';$('#scenario-results').innerHTML=scenarioResults();persist();}});
document.addEventListener('keydown',e=>{if(e.target.matches('textarea')&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();e.target.form.requestSubmit();}if(e.target.hasAttribute('data-month')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(!$('#presentation').hidden){if(e.key==='Escape')exitPresentation();if(e.key==='ArrowRight'){slideIndex=Math.min(2,slideIndex+1);renderSlide();}if(e.key==='ArrowLeft'){slideIndex=Math.max(0,slideIndex-1);renderSlide();}if(e.key==='Tab'){const focusable=$$('#presentation button:not([disabled])'),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}});
window.addEventListener('hashchange',()=>render());render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_prometeu_dashboard',title:'Configurar dashboard Prometeu',description:'Altera filtros ou o gráfico de evolução da análise local atual e abre o dashboard.',inputSchema:{type:'object',properties:{area:{type:'string'},period:{type:'string'},chartType:{type:'string',enum:['bar','line','table']}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(!input||typeof input!=='object')throw Error('Configuração inválida');const rows=sourceRows();if(input.area&&input.area!=='Todas as áreas'&&!rows.some(r=>r.area===input.area))throw Error('Área indisponível');if(input.period&&!rows.some(r=>r.date.startsWith(input.period)))throw Error('Período indisponível');if(input.chartType&&!['bar','line','table'].includes(input.chartType))throw Error('Tipo inválido');if(Object.keys(input).some(k=>!['area','period','chartType'].includes(k)))throw Error('Campo desconhecido');if(input.area)dash().area=input.area;if(input.period)dash().period=input.period;if(input.chartType){dash().trendType=input.chartType;if(dash().pro){const p=dash().pro,w=p.widgets.trend||Object.values(p.widgets).find(w=>['column','bar','line','area','table'].includes(w.type));if(w){w.type=input.chartType==='bar'?'column':input.chartType;p.selected=w.id;p.activePage=p.pages.find(pg=>pg.widgets.includes(w.id))?.id||p.activePage;}}}persist();history.replaceState(null,'','#dashboard');render();return {title:dash().title,area:dash().area,period:dash().period,chartType:dash().trendType,records:selectRows().length};}})).catch(()=>{});}catch{}}
